-- ISOLATED TEST DATABASE ONLY. No production data or credentials.
create role anon;
create role authenticated;
create schema private;
create function private.is_pricing_admin() returns boolean language sql as $$ select coalesce(current_setting('app.staff',true),'')='true' $$;
create function private.is_commerce_admin() returns boolean language sql as $$ select private.is_pricing_admin() $$;
create function private.require_internal_staff() returns void language plpgsql as $$ begin if not private.is_pricing_admin() then raise exception 'Acceso no autorizado' using errcode='42501'; end if; end $$;
create table pricing_rule_definitions(rule_key text primary key,rule_type text,label text,value_kind text,required boolean,active boolean,sort_order integer);
create table pricing_catalog_versions(id uuid primary key default gen_random_uuid(),version integer unique,status text,note text,published_at timestamptz,updated_at timestamptz default now());
create unique index one_published on pricing_catalog_versions(status) where status='published';
create table pricing_catalog_values(version_id uuid references pricing_catalog_versions,rule_key text references pricing_rule_definitions,value numeric,primary key(version_id,rule_key));
create function public.get_published_pricing_catalog() returns jsonb language sql as $$ select jsonb_build_object('versionId',id,'version',version,'rules',(select jsonb_object_agg(rule_key,value) from public.pricing_catalog_values where version_id=v.id)) from public.pricing_catalog_versions v where status='published' $$;
create table commerce_products(id uuid primary key,name text,category_code text,category text);
create table commerce_variants(id uuid primary key,product_id uuid references commerce_products,sku text,name text,active boolean,available_local boolean);
create table local_sales_customers(id uuid primary key,full_name text,first_purchase_date date,last_purchase_date date);
create table local_sales(id uuid primary key default gen_random_uuid(),sale_number bigint generated always as identity,reference_code text default '#TEST',created_at timestamptz default now(),customer_id uuid,customer_name text,sold_on date,payment_method text,total_minor bigint,channel text);
create view orders as select id,channel from local_sales;
create table order_items(id uuid primary key,order_id uuid references local_sales,item_type text check(item_type in ('catalog','design')),source_variant_id uuid references commerce_variants,sku text,title text,quantity integer,unit_price_minor bigint,total_minor bigint,immutable_snapshot jsonb,requires_review boolean,created_at timestamptz,production_status text);
create view local_sale_items as select id,order_id sale_id,source_variant_id variant_id,coalesce(sku,'') sku,immutable_snapshot->>'productName' product_name,immutable_snapshot->>'variantName' variant_name,quantity,unit_price_minor,total_minor line_total_minor,created_at,production_status,immutable_snapshot->'customization' customization,immutable_snapshot->>'productionNotes' production_notes from order_items;
